                vis[i][j]=True
                q.append((i,j))
    while q:
        a,b=q.popleft()
        for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
            na,nb=a+da,b+db
            if 0<=na<H and 0<=nb<W and not vis[na][nb] and g[na][nb]!=val:
                vis[na][nb]=True; q.append((na,nb))
    # count cells inside bbox not visited
    return sum(1 for i in range(rs,rs+h) for j in range(cls,cls+w) if not vis[i][j])
