def analyze(n):
    gin=G[f'Demo pair {n} input']; go=G[f'Demo pair {n} output']
    H,W=len(gin),len(gin[0])
    cnt=Counter(x for r in gin for x in r); bg=cnt.most_common(1)[0][0]
    res=[]
    for vv in sorted({x for r in gin for x in r}-{bg}):
        for cc in comps(gin,vv):
            s=set(cc)
            rs=[p[0] for p in cc]; cls=[p[1] for p in cc]
            r0,c0=min(rs),min(cls); h=max(rs)-r0+1; w=max(cls)-c0+1
            bbox=[(i,j) for i in range(r0,r0+h) for j in range(c0,c0+w)]
            nb=[(1,0),(-1,0),(0,1),(0,-1)]
            # flood bg from bbox border cells outside comp
            vis=set(); q=deque(); outside=False
            for i,j in bbox:
                if (i,j) not in s:
                    if i<0 or i>=H or j<0 or j>=W: outside=True
                    else: vis.add((i,j)); q.append((i,j))
            enc=0
            while q:
                a,b=q.popleft()
                if a==r0-1 or a==r0+h or b==c0-1 or b==c0+w: outside=True
                for da,db in nb:
                    n2,n3=a+da,b+db
                    if 0<=n2<H and 0<=n3<W and gin[n2][n3]==bg and (n2,n3) not in vis:
                        vis.add((n2,n3)); q.append((n2,n3))
            enc=sum(1 for i in range(r0,r0+h) for j in range(c0,c0+w) if gin[i][j]==bg and (i,j) not in vis)
            touch = any(p[0]==0 or p[0]==H-1 or p[1]==0 or p[1]==W-1 for p in cc)
            res.append({'color':vv,'size':len(s),'miss':h*w-len(s),'enclosed_bg':enc,'touch':touch,'pos':(r0,c0)})
    changed=sorted(set(go[i][j] for i in range(H) for j in range(W) if go[i][j]!=gin[i][j]))
    print(f'--- demo {n} bg={bg} -> {changed}')
    for r_ in res:
        print('   ',r_)
