    rs=[p[0] for p in cc]; cls=[p[1] for p in cc]
    r0,c0,r1,c1=min(rs),min(cls),max(rs),max(cls)
    vis={(r0-1,c0-1)}; q=deque([(r0-1,c0-1)])
    bg=Counter(x for r in gin for x in r).most_common(1)[0][0]
    reach=True
    dirs=((1,0),(-1,0),(0,1),(0,-1))
    while q:
        a,b=q.popleft()
        for da,db in dirs:
            n2,n3=a+da,b+db
            if 0<=n2<H and 0<=n3<W and gin[n2][n3]==bg and (n2,n3) not in vis:
                vis.add((n2,n3)); q.append((n2,n3))
                if n2<r0-1 or n2>r1+1 or n3<c0-1 or n3>c1+1: reach=False
    total=r1-r0+1*c1-c0+1
    # enclosed bg = cells inside bbox not on comp, not reached via bg path connected to bbox exterior
    vis2=set(cc); q2=deque(list(zip(range(r0,r1+1),range(c0,c1+1))))
    # flood bg only within bbox+border region
    visb={}; q3=deque()
    for i in range(max(0,r0-1),min(H-1,r1+1)+1):
        for j in range(max(0,c0-1),min(W-1,c1+1)+1):
            if gin[i][j]==bg and (i,j) not in visb:
                visb[(i,j)]=1; q3.append((i,j))
    while q3:
        a,b=q3.popleft()
        for da,db in dirs:
            n2,n3=a+da,b+db
            if 0<=n2<H and 0<=n3<W and gin[n2][n3]==bg and (n2,n3) not in visb:
                visb[(n2,n3)]=1; q3.append((n2,n3))
    return sum(1 for i in range(r0,r1+1) for j in range(c0,c1+1) if gin[i][j]==bg and (i,j) not in visb)
