import itertools
def symm(cells):
    rs=[p[0] for p in cells]; cls=[p[1] for p in cells]
    r0,r1,c0,c1=min(rs),max(rs),min(cls),max(cls)
    h,w=r1-r0+1,w-c0+1
    res=[]
    for dy in range(2):
        for dx in range(2):
            # flip rows if dy, flip cols if dx
            fr=lambda a:(a-r0)*(-1)+r1 if dy else a-r0+r0
            fc=lambda b:(b-c0)*(-1)+c1 if dx else b-c0+c0
            for a,b in cells:
                ra,rb=fr(a),fc(b)
                res.append((ra,rb))
    return sorted(res)
