def comps(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if not seen[i][j] and g[i][j]!=2:  # treat most common as background? fix later; use != most common color
                v=g[i][j]; stack=[(i,j)]; cells=[]
                while stack:
                    r,c=stack.pop()
