                    seen[r][c]=True; cells.append((r,c))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=r+dr,c+dc
                        if 0<=nr<H and 0<=nc<W and not seen[nr][nc] and g[nr][nc]==v:
                            stack.append((nr,nc))
                out.append((v,cells))
    return out
